#include <bits/stdc++.h>

using namespace std;

void solve() {
    int n, m;
    cin >> n >> m;
    vector<string> a(n);
    for (auto &i: a) {
        cin >> i;
    }
    vector<vector<string>> b(m, vector<string>(n));
    for (auto &ar: b) {
        for (auto &s: ar) {
            cin >> s;
        }
    }
    vector<bool> exists(n);
    int x = 0;
    for (int i = 0; i < m; i++) {
        int cnt = 0;
        for (int j = 0; j < n; j++) {
            if (a[j] == b[i][j]) {
                cnt++;
                exists[j] = true;
            }
        }
        x = max(x, cnt);
    }
    if (all_of(exists.begin(), exists.end(), identity())) {
        cout << n + 2 * (n - x) << "\n";
    } else {
        cout << "-1\n";
    }
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
